@test
def test_compute_rank():
    nr = ["M1", "M2", "G1", "G2", "E1", "E2"]
    ir = mne.create_info(nr, 100.0, ["mag", "mag", "grad", "grad", "eeg", "eeg"])
    rr0 = np.random.RandomState(8)
    xr = rr0.randn(6, 50)
    xr[1] = xr[0]
    xr[5] = xr[4] * 2
    xr[:2] *= 1e-12
    xr[2:4] *= 1e-11
    xr[4:] *= 1e-5
    raw = mne.io.RawArray(xr, ir)
    rk = mne.compute_rank(raw)
    assert rk["meg"] == 3
    assert rk["eeg"] == 1
    ri = mne.compute_rank(raw, rank="info")
    assert ri["meg"] == 4
    assert ri["eeg"] == 2
test_compute_rank()


def grid_mesh():
    nx = 6
    vtx = np.zeros((nx * nx, 3))
    for i in range(nx):
        for j in range(nx):
            vtx[i * nx + j, 0] = float(i)
            vtx[i * nx + j, 1] = float(j)
            vtx[i * nx + j, 2] = 0.1 * np.sin(float(i + j))
    tri = np.zeros((2 * (nx - 1) * (nx - 1), 3), dtype=int)
    k = 0
    for i in range(nx - 1):
        for j in range(nx - 1):
            a = i * nx + j
            tri[k, 0] = a
            tri[k, 1] = a + 1
            tri[k, 2] = a + nx
            tri[k + 1, 0] = a + 1
            tri[k + 1, 1] = a + nx + 1
            tri[k + 1, 2] = a + nx
            k += 2
    return vtx, tri


@test
def test_grow_labels():
    vtx, tri = grid_mesh()
    surfaces = {"lh": (vtx, tri)}
    labs = mne.grow_labels("s", [[0], [20, 21], [35]], [2.5, 1.5, 3.0], 0, names=["a", "b", "c"], surfaces=surfaces)
    assert labs[0].vertices.tolist() == [0, 1, 2, 6, 7, 12]
    close("gl0", labs[0].values, [0.0, 1.0, 2.0, 1.0, 2.0, 2.0])
    assert labs[1].vertices.tolist() == [14, 15, 16, 19, 20, 21, 22, 25, 26, 27]
    close("gl1", labs[1].values, [1.0, 1.0, 1.0, 1.0, 0.0, 0.0, 1.0, 1.0, 1.0, 1.0])
    assert labs[2].vertices.tolist() == [23, 28, 29, 33, 34, 35]
    close("gl2", labs[2].values, [2.0, 2.0, 1.0, 2.0, 1.0, 0.0])
    assert labs[0].name == "a-lh"
    lab2 = mne.grow_labels("s", [[0], [20, 21], [35]], [2.5, 1.5, 3.0], 0, names=["a", "b", "c"], overlap=False, surfaces=surfaces)
    assert lab2[0].vertices.tolist() == [0, 1, 2, 6, 7, 12]
    assert lab2[1].vertices.tolist() == [14, 15, 16, 19, 20, 21, 22, 25, 26, 27]
    assert lab2[2].vertices.tolist() == [29, 34, 35]

test_grow_labels()


@test
def test_random_parcellation():
    vtx, tri = grid_mesh()
    labs = mne.random_parcellation("s", 4, "lh", random_state=11, surfaces={"lh": (vtx, tri)})
    assert len(labs) == 4
    assert labs[0].vertices.tolist() == [13, 14, 18, 19, 20, 24, 25, 26, 30, 31]
    assert labs[1].vertices.tolist() == [3, 4, 5, 8, 9, 10, 11, 15, 16, 21]
    assert labs[2].vertices.tolist() == [17, 22, 23, 27, 28, 29, 32, 33, 34, 35]
    assert labs[3].vertices.tolist() == [0, 1, 2, 6, 7, 12]
test_random_parcellation()


